import { z } from 'zod';
import { DomainError, notImplemented, type UseCase, type UseCaseContext } from '@agentic-ddd/core';
import { AgentUseCase } from '@agentic-ddd/decorators';
import { Task } from '../domain/task';
import { TaskCreated } from '../domain/task.events';
import type { TaskRepository } from '../domain/task.repository';

export const createTaskInput = z.object({ task_id: z.string().min(1), title: z.string().min(1) });
export const createTaskOutput = z.object({ task_id: z.string(), title: z.string(), status: z.literal('pending') });
export type CreateTaskInput = z.infer<typeof createTaskInput>;
export type CreateTaskOutput = z.infer<typeof createTaskOutput>;

@AgentUseCase({ name: 'create_task', description: 'Cria, salva e publica uma tarefa pendente; id repetido falha com TASK_ALREADY_EXISTS.', whenToUse: 'Quando o usuário deseja criar uma tarefa.', whenNotToUse: 'Para concluir tarefa existente.', input: createTaskInput, output: createTaskOutput, uses: ['method:Task.create'], emits: [TaskCreated] })
export class CreateTask implements UseCase<CreateTaskInput, CreateTaskOutput> {
  constructor(private readonly tasks: TaskRepository) {}
  async execute(input: CreateTaskInput, ctx: UseCaseContext): Promise<CreateTaskOutput> {
    if (await this.tasks.findById(input.task_id)) {
      throw new DomainError('TASK_ALREADY_EXISTS', 'Já existe uma tarefa com este id.');
    }
    const task = Task.create(input.task_id, input.title);
    await this.tasks.save(task);
    await ctx.publish(task.pullEvents());
    return { task_id: task.id, title: task.title, status: 'pending' };







  }
}

import { expect, mock, test } from 'bun:test';
import { DomainError } from '@agentic-ddd/core';
import { covers, createTestContext } from '@agentic-ddd/testing';
import { CreateTask } from '../application/create-task';
import { Task } from '../domain/task';
import { TaskCreated } from '../domain/task.events';
import { InMemoryTaskRepository } from '../infrastructure/in-memory-task.repository';

test(covers([
  'usecase:create_task',
  'criterion:0001/persistencia-criacao',
], 'salva t1 antes de publicar TaskCreated, retorna pending e rejeita id repetido'), async () => {
  const persisted = new InMemoryTaskRepository();
  const operations: string[] = [];
  const repository = {
    async findById(id: string) {
      operations.push(`load:${id}`);
      return persisted.findById(id);
    },
    async save(task: Task) {
      await Promise.resolve();
      await persisted.save(task);
      operations.push(`save:${task.id}`);
    },
  };
  const context = createTestContext();
  const ctx = {
    ...context,
    async publish(events: Parameters<typeof context.publish>[0]) {
      operations.push('publish');
      expect((await persisted.findById('t1'))?.status).toBe('pending');
      await context.publish(events);
    },
  };
  const useCase = new CreateTask(repository);
  const output = await useCase.execute({ task_id: 't1', title: ' \tComprar  pão\n ' }, ctx);

  expect(output).toEqual({ task_id: 't1', title: 'Comprar  pão', status: 'pending' });
  expect(operations).toEqual(['load:t1', 'save:t1', 'publish']);
  const saved = await persisted.findById('t1');
  expect(saved).toBeInstanceOf(Task);
  expect(saved?.title).toBe('Comprar  pão');
  expect(saved?.status).toBe('pending');
  expect(context.published).toHaveLength(1);
  expect(context.published[0]).toBeInstanceOf(TaskCreated);
  expect(context.published[0]!.payload).toEqual({ taskId: 't1', title: 'Comprar  pão' });
  expect(saved?.pullEvents()).toEqual([]);

  const duplicate = useCase.execute({ task_id: 't1', title: 'Outro título' }, ctx);
  await expect(duplicate).rejects.toBeInstanceOf(DomainError);
  await expect(duplicate).rejects.toMatchObject({ code: 'TASK_ALREADY_EXISTS' });
  expect(operations).toEqual(['load:t1', 'save:t1', 'publish', 'load:t1']);
  expect(await persisted.findById('t1')).toBe(saved);
  expect(saved?.title).toBe('Comprar  pão');
  expect(context.published).toHaveLength(1);
});

test(covers([
  'usecase:create_task',
], 'propaga TASK_TITLE_REQUIRED sem salvar ou publicar título em branco'), async () => {
  const repository = {
    findById: mock(async (_id: string): Promise<Task | null> => null),
    save: mock(async (_task: Task) => {}),
  };
  const context = createTestContext();
  const publish = mock(context.publish);
  const execution = new CreateTask(repository).execute({ task_id: 't1', title: ' \t\n ' }, {
    ...context, publish,
  });

  await expect(execution).rejects.toBeInstanceOf(DomainError);
  await expect(execution).rejects.toMatchObject({ code: 'TASK_TITLE_REQUIRED' });
  expect(repository.save).not.toHaveBeenCalled();
  expect(publish).not.toHaveBeenCalled();
  expect(context.published).toEqual([]);
});

test(covers([
  'usecase:create_task',
], 'aguarda gravação e propaga sua falha sem publicar eventos'), async () => {
  const failure = new Error('Falha ao salvar');
  const repository = {
    async findById(_id: string): Promise<Task | null> { return null; },
    async save(_task: Task) {
      await Promise.resolve();
      throw failure;
    },
  };
  const context = createTestContext();
  const publish = mock(context.publish);

  await expect(new CreateTask(repository).execute({ task_id: 't1', title: 'Comprar pão' }, {
    ...context, publish,
  })).rejects.toBe(failure);
  expect(publish).not.toHaveBeenCalled();
  expect(context.published).toEqual([]);
});

test(covers([
  'usecase:create_task',
], 'propaga falha de publicação após persistir a tarefa'), async () => {
  const repository = new InMemoryTaskRepository();
  const context = createTestContext();
  const failure = new Error('Falha ao publicar');
  const publish = mock(async (_events: Parameters<typeof context.publish>[0]) => {
    await Promise.resolve();
    throw failure;
  });

  await expect(new CreateTask(repository).execute({ task_id: 't1', title: 'Comprar pão' }, {
    ...context, publish,
  })).rejects.toBe(failure);
  expect((await repository.findById('t1'))?.status).toBe('pending');
  expect(publish).toHaveBeenCalledTimes(1);
  expect(publish.mock.calls[0]![0][0]).toBeInstanceOf(TaskCreated);
});
